records
    .map((record) => {
      const tags =
        record.tags.length > 0 ? ` (tags: ${record.tags.join(", ")})` : "";
      const summary = record.summary.trim() || record.content.slice(0, 120);
      return `[${record.id}] [${record.source}] ${record.title} — ${summary}${tags}`;
    })
    .join

[...selectedIds]
        .map((id) => {
          // 先在 Tier2 重排结果中找，再回退到排序后的池
          const record =
            tier2Ranked.find((r) => r.record.id === id)?.record ??
            sorted.find((r) => r.id === id);
          if (!record) return null;
          return {
            record,
            score: scoreById.get(id) ?? LLM_FALLBACK_SCORE,
          };
        })
        .filter(
          (
            item,
          ): item is { record: MemoryRecord; score: number } =>
            item !== null,
        )
        .slice

